// Workflow D · Format offers (Task 3.5 contract — no date math, labels come from Django)
const body = $input.item.json.body || $input.item.json;

const patientName  = body.patient_name || 'Patient';
const patientPhone = body.patient_phone || '';
const serviceName  = body.service_name || 'Consultation';
const clinicName   = body.clinic_name || 'Clinic';
const requestId    = body.request_id || '';
const chatId       = body.telegram_chat_id || null;
const expiryMin    = body.expiry_minutes || 60;
const channels     = Array.isArray(body.dispatch_channels)
  ? body.dispatch_channels : ['whatsapp', 'sms', 'voice'];
const slots        = body.candidate_slots || [];

const numberEmojis = ['1️⃣', '2️⃣', '3️⃣', '4️⃣'];

// Options MUST stay in payload order — Workflow C resolves "2" against this order.
const options = slots.map((slot, idx) => ({
  number: idx + 1,
  emoji: numberEmojis[idx] || `${idx + 1}.`,
  slot_offer_id: slot.id,
  doctor_name: slot.doctor_name || 'Doctor',
  date_label: slot.date_label || '',
  time_label: slot.time_label || '',
  label: `${numberEmojis[idx] || (idx + 1) + '.'} ${slot.date_label} at ${slot.time_label} (${slot.doctor_name})`,
}));

const optionsText = options.map(o => `\n${o.emoji} ${o.date_label} at ${o.time_label} (${o.doctor_name})`).join('');

const smsBody =
  `${clinicName}: Your ${serviceName} slots are ready.` +
  options.map(o => ` ${o.number}) ${o.date_label} ${o.time_label} (${o.doctor_name})`).join('') +
  ` Reply 1, 2, or ${options.length} to lock in your time. Held for ${expiryMin} minutes.`;

const messageText =
  `✨ <b>Available Appointment Times</b>\n\n` +
  `Hello <b>${patientName}</b>, our front desk has reviewed your request for <b>${serviceName}</b> and reserved the following options for you:\n` +
  `${optionsText}\n\n` +
  `⏳ <i>Please tap your preferred time below to confirm. These options are held for <b>${expiryMin} minutes</b> so that all patients have fair access to the doctor's calendar.</i>`;

const inlineKeyboard = options.map(o => ([
  { text: o.label, callback_data: `select_slot_${o.slot_offer_id}` },
]));

return {
  json: {
    // Existing fields (Respond node + Telegram node keep working)
    channel: body.channel || 'web',
    chat_id: chatId,
    patient_name: patientName,
    request_id: requestId,
    message_text: messageText,
    inline_keyboard: inlineKeyboard,
    slots_count: options.length,
    // Task 3.5 additions for the channel legs
    clinic_name: clinicName,
    patient_phone: patientPhone,
    service_name: serviceName,
    expiry_minutes: expiryMin,
    offer_expires_at: body.offer_expires_at || '',
    options,
    options_text: optionsText,
    sms_body: smsBody,
    whatsapp_params: options.map(o => o.label),
    want_whatsapp: channels.includes('whatsapp'),
    want_sms: channels.includes('sms'),
    want_voice: channels.includes('voice'),
  },
};

// Workflow D · Provider Config & Adapter (single source of provider config)
// Reads deployment config from $env — no node hardcodes a URL, key or sender id.
// Emits ONE item per active channel (want_* + the chat_id rule), so no IF nodes are needed.
//
// Mock mode (PROVIDER_MOCK unset or true) does NOT skip the send nodes: it points every
// provider URL at the in-cluster Provider Simulator workflow (06_Provider_Simulator), so
// the real HTTP nodes, their bodies and the real failure path are exercised today.
// Flip-live = PROVIDER_MOCK=false + real VOICEBIP_* / WHATSAPP_* values.
const src = $input.all()[0].json;

const env = (name, fallback = '') => {
  try { const v = $env[name]; return (v === undefined || v === null) ? fallback : String(v); }
  catch (e) { return fallback; }
};
const truthy = (v) => ['1', 'true', 'yes', 'on'].includes(String(v).trim().toLowerCase());

const providerMock = env('PROVIDER_MOCK') === '' ? true : truthy(env('PROVIDER_MOCK'));
const providerMockFail = truthy(env('PROVIDER_MOCK_FAIL'));

const cfg = {
  voicebipApiUrl: env('VOICEBIP_API_URL'),
  voicebipApiKey: env('VOICEBIP_API_KEY'),
  voiceAgentId: env('VOICEBIP_VOICE_AGENT_ID'),
  callerId: env('VOICEBIP_CALLER_ID'),
  smsSenderId: env('VOICEBIP_SMS_SENDER_ID', 'Cedarcare'),
  whatsappApiUrl: env('WHATSAPP_API_URL', 'https://graph.facebook.com/v19.0/'),
  whatsappPhoneId: env('WHATSAPP_PHONE_NUMBER_ID'),
  whatsappToken: env('WHATSAPP_ACCESS_TOKEN'),
  simulatorUrl: env('PROVIDER_SIMULATOR_URL', 'http://127.0.0.1:5678/webhook/provider-sim'),
};

const requestId = src.request_id || '';
const patientPhone = src.patient_phone || '';
const optionsCount = src.slots_count || (src.options ? src.options.length : 0);
const expiryMinutes = src.expiry_minutes || 60;

// Which channels should fire. The WhatsApp leg is the instant-message checkbox;
// a patient with a Telegram chat already got the Telegram card from Django itself.
const active = [];
if (src.want_whatsapp && !src.chat_id) active.push('whatsapp');
if (src.want_sms) active.push('sms');
if (src.want_voice) active.push('voice');

const configured = providerMock
  ? { whatsapp: true, sms: true, voice: true }
  : {
      sms: Boolean(cfg.voicebipApiUrl && cfg.voicebipApiKey),
      voice: Boolean(cfg.voicebipApiUrl && cfg.voicebipApiKey && cfg.voiceAgentId),
      whatsapp: Boolean(cfg.whatsappPhoneId && cfg.whatsappToken),
    };

// Voice quiet-hours gate (08:00–19:00 Africa/Lagos) — a gate, not date math for labels.
let voiceInWindow = true;
try {
  const lagosHour = Number(new Intl.DateTimeFormat('en-GB', { timeZone: 'Africa/Lagos', hour: 'numeric', hour12: false }).format(new Date()));
  voiceInWindow = lagosHour >= 8 && lagosHour < 19;
} catch (e) { voiceInWindow = true; }

// Dedupe guard (best-effort; static data is not persisted in manual test runs —
// Django's PATIENT_ALREADY_BOOKED + offer state remain authoritative).
const seen = {};
try {
  const sd = $getWorkflowStaticData('global');
  sd.seen = sd.seen || {};
  const now = Date.now();
  for (const k of Object.keys(sd.seen)) { if (now - sd.seen[k] > 600000) delete sd.seen[k]; }
  for (const ch of active) {
    const key = requestId + ':' + ch;
    if (sd.seen[key]) seen[ch] = true; else sd.seen[key] = now;
  }
} catch (e) { /* static data unavailable */ }

const buildRequest = (channel) => {
  if (providerMock) {
    // Same request shape, different destination: the simulator answers in-cluster.
    const headers = { Authorization: 'Bearer mock' };
    const body = channel === 'sms'
      ? { to: patientPhone, message: src.sms_body || '', sender_id: cfg.smsSenderId,
          metadata: { request_code: requestId, channel } }
      : channel === 'voice'
        ? { to: patientPhone, agent_id: 'mock-agent', caller_id: 'mock-caller',
            metadata: { request_code: requestId, channel },
            variables: { patient_name: src.patient_name || 'Patient',
                         clinic_name: src.clinic_name || 'Clinic',
                         service_name: src.service_name || 'Consultation',
                         options_count: optionsCount, expiry_minutes: expiryMinutes } }
        : { messaging_product: 'whatsapp', to: patientPhone, type: 'text',
            text: { body: src.sms_body || src.message_text || '' },
            metadata: { request_code: requestId, channel } };
    return { url: cfg.simulatorUrl + '/' + channel, headers, body };
  }

  if (channel === 'sms') {
    return {
      url: cfg.voicebipApiUrl + '/sms',
      headers: { Authorization: 'Bearer ' + cfg.voicebipApiKey },
      body: { to: patientPhone, message: src.sms_body || '', sender_id: cfg.smsSenderId,
              metadata: { request_code: requestId, channel: 'sms' } },
    };
  }
  if (channel === 'voice') {
    return {
      url: cfg.voicebipApiUrl + '/voice/calls',
      headers: { Authorization: 'Bearer ' + cfg.voicebipApiKey },
      body: { to: patientPhone, agent_id: cfg.voiceAgentId, caller_id: cfg.callerId,
              metadata: { request_code: requestId, channel: 'voice' },
              variables: { patient_name: src.patient_name || 'Patient',
                           clinic_name: src.clinic_name || 'Clinic',
                           service_name: src.service_name || 'Consultation',
                           options_count: optionsCount, expiry_minutes: expiryMinutes } },
    };
  }
  return {
    url: cfg.whatsappApiUrl + cfg.whatsappPhoneId + '/messages',
    headers: { Authorization: 'Bearer ' + cfg.whatsappToken },
    body: { messaging_product: 'whatsapp', to: patientPhone, type: 'text',
            text: { body: src.sms_body || src.message_text || '' },
            metadata: { request_code: requestId, channel: 'whatsapp' } },
  };
};

const out = active.map((channel) => {
  let route = channel;
  let skipReason = null;
  if (seen[channel]) { route = 'skip'; skipReason = 'duplicate_dispatch'; }
  else if (channel === 'voice' && !voiceInWindow) { route = 'skip'; skipReason = 'outside_call_window'; }
  else if (!configured[channel]) { route = 'skip'; skipReason = 'provider_not_configured'; }

  return { json: {
    ...src,
    provider_channel: channel,
    provider_request: {
      route,
      skip_reason: skipReason,
      method: 'POST',
      ...buildRequest(channel),
    },
    adapter_meta: {
      channel,
      provider_mock: providerMock,
      provider_mock_fail: providerMockFail,
      configured: configured[channel],
      voice_in_window: voiceInWindow,
      duplicate: Boolean(seen[channel]),
      request_id: requestId,
      external_ref_hint: 'mock-' + channel + '-' + requestId,
      missing_env: providerMock ? [] : Object.entries({
        VOICEBIP_API_URL: cfg.voicebipApiUrl,
        VOICEBIP_API_KEY: cfg.voicebipApiKey,
        VOICEBIP_VOICE_AGENT_ID: cfg.voiceAgentId,
        VOICEBIP_CALLER_ID: cfg.callerId,
        WHATSAPP_PHONE_NUMBER_ID: cfg.whatsappPhoneId,
        WHATSAPP_ACCESS_TOKEN: cfg.whatsappToken,
        DJANGO_WEBHOOK_SECRET: env('DJANGO_WEBHOOK_SECRET'),
      }).filter(([, v]) => !v).map(([k]) => k),
    },
  } };
});

return out.length ? out : [{ json: { ...src, provider_channel: null, provider_request: { route: 'skip', skip_reason: 'no_active_channel', method: 'POST', url: '', headers: {}, body: null }, adapter_meta: { channel: null, provider_mock: providerMock, provider_mock_fail: providerMockFail, configured: false, voice_in_window: voiceInWindow, duplicate: false, request_id: requestId, external_ref_hint: null, missing_env: [] } } }];

// Workflow D · Stage D-2 — reattach the voice payload after the 30s status probe.
// The probe response replaces the item, but the send/log nodes need the adapter payload,
// so pull the voice item back from the adapter and record why we did (or didn't) call.
const probe = $input.first().json || {};

const voiceItem = $('Provider Config & Adapter').all()
  .map(i => i.json)
  .find(j => j && j.provider_channel === 'voice');

const truthy = (v) => v === true || v === 'true' || v === 1 || v === '1';
const shouldSkip = truthy(probe.should_skip_voice_call);

// Fail safe: if the adapter payload is missing, do NOT place a call.
const payload = voiceItem || {
  provider_channel: 'voice',
  provider_request: { route: 'skip', skip_reason: 'voice_payload_missing' },
};

return [{ json: {
  ...payload,
  provider_request: shouldSkip
    ? { ...(payload.provider_request || {}), route: 'skip', skip_reason: 'patient_already_engaged' }
    : payload.provider_request,
  voice_guard: {
    checked: true,
    checked_at: new Date().toISOString(),
    wait_seconds: 30,
    should_skip: shouldSkip,
    request_status: probe.status || null,
    has_active_hold: truthy(probe.has_active_hold),
    has_confirmed_booking: truthy(probe.has_confirmed_booking),
    appointment_code: probe.appointment_code || null,
  },
} }];

// Workflow D · Stage D-3 — log the provider outcome to Django (authoritative record).
// Runs for BOTH the success and the error output of the send node: the dashboard's
// Needs Attention tab reads InteractionLog rows with status failed / no_answer.
const incoming = $input.first().json || {};
const base = $('Provider Config & Adapter').all()
  .map(i => i.json)
  .find(j => j && j.provider_channel === 'whatsapp') || {};

const isError = Boolean(incoming.error);
const resp = isError ? {} : incoming;

// n8n wraps HTTP failures as: 500 - "{\"error\":\"...\",\"detail\":\"...\"}"
// Pull the provider's own sentence out so reception reads plain language.
const humanError = (err) => {
  const raw = String((err && err.message) || err || '');
  const jsonPart = raw.match(/\{[\s\S]*\}/);
  if (jsonPart) {
    try {
      const parsed = JSON.parse(jsonPart[0].replace(/\\"/g, '"'));
      const msg = parsed.detail || parsed.message || parsed.error;
      if (msg) return String(msg).slice(0, 300);
    } catch (e) { /* fall through to raw */ }
  }
  return raw.slice(0, 300);
};

const providerStatus = String(resp.status || '').toLowerCase();
const failed = isError || providerStatus === 'failed' || resp.ok === false;

const errorDetail = isError
  ? humanError(incoming.error)
  : (failed ? String(resp.error || resp.detail || 'Provider reported a failure').slice(0, 300) : '');

const payload = {
  provider: 'meta_whatsapp',
  channel: 'whatsapp',
  direction: 'outbound',
  status: failed ? 'failed' : 'sent',
  patient_name: base.patient_name || '',
  patient_phone: base.patient_phone || '',
  request_code: base.request_id || '',
  external_ref: failed ? '' : (resp.external_ref || resp.message_id || resp.id || resp.call_id || ''),
  summary: 'Appointment options sent via WhatsApp',
  error_detail: errorDetail,
};

let logged = { ok: false };
try {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: $env.DJANGO_API_BASE_URL + '/interactions/',
    headers: { 'Content-Type': 'application/json', 'X-Webhook-Secret': $env.DJANGO_WEBHOOK_SECRET || '' },
    body: payload,
    json: true,
  });
  logged = { ok: true, id: res.id, status: res.status };
} catch (e) {
  logged = { ok: false, error: (e.message || String(e)).slice(0, 300) };
}

return [{ json: { ...base, provider_response: resp, interaction_log: { ...logged, payload } } }];

